1	package txsaga
2	
3	import (
4		"context"
5		"time"
6	)
7	
8	// Publisher 由调用方实现，负责把一条 Outbox 事件发送到实际的下游
9	// （消息代理、HTTP 回调、其它进程内通道等）。本包不提供任何具体中间件适配。
10	//
11	// 实现应当满足至少一次投递语义：返回 error 时事件会被保留并可再次领取，
12	// 因此下游消费侧需要自身幂等。返回 nil 即视为投递成功，事件被标记已投递。
13	type Publisher interface {
14		// Publish 发送单个事件。event.Payload 为结构化负载，可用 encoding/json 序列化。
15		Publish(ctx context.Context, event Event) error
16	}
17	
18	// PublisherFunc 让普通函数满足 Publisher 接口。
19	type PublisherFunc func(ctx context.Context, event Event) error
20	
21	// Publish 实现 Publisher 接口。
22	func (f PublisherFunc) Publish(ctx context.Context, event Event) error { return f(ctx, event) }
23	
24	// Relay 在 Store 与 Publisher 之间搬运 Outbox 事件：
25	// 领取待投递事件、交给 Publisher、成功 Ack、失败 Nack 后保留并允许重试。
26	// Relay 可被多个 worker 并发使用；零值不可用，请用 NewRelay 创建。
27	type Relay struct {
28		store     Store
29		publisher Publisher
30		// batch 单次领取上限。
31		batch int
32		// retryBackoff 一批事件全部发送失败后的再次领取间隔。
33		retryBackoff time.Duration
34		// idleWait 没有待投递事件时的轮询等待。
35		idleWait time.Duration
36		// now 等时间依赖直接使用 time 包标准行为。
37		sleep func(ctx context.Context, d time.Duration) error
38	}
39	
40	// RelayOption 配置 Relay。
41	type RelayOption func(*Relay)
42	
43	// WithBatch 设置单次领取事件数，默认 16。
44	func WithBatch(n int) RelayOption {
45		return func(r *Relay) {
46			if n > 0 {
47				r.batch = n
48			}
49		}
50	}
51	
52	// WithRetryBackoff 设置发送失败后的重试间隔，默认 200ms。
53	func WithRetryBackoff(d time.Duration) RelayOption {
54		return func(r *Relay) {
55			if d > 0 {
56				r.retryBackoff = d
57			}
58		}
59	}
60	
61	// WithIdleWait 设置无事件时的轮询间隔，默认 500ms。
62	func WithIdleWait(d time.Duration) RelayOption {
63		return func(r *Relay) {
64			if d > 0 {
65				r.idleWait = d
66			}
67		}
68	}
69	
70	// NewRelay 创建事件投递器。
71	func NewRelay(store Store, publisher Publisher, opts ...RelayOption) *Relay {
72		r := &Relay{
73			store:        store,
74			publisher:    publisher,
75			batch:        16,
76			retryBackoff: 200 * time.Millisecond,
77			idleWait:     500 * time.Millisecond,
78		}
79		r.sleep = sleepWithContext
80		for _, opt := range opts {
81			opt(r)
82		}
83		return r
84	}
85	
86	func sleepWithContext(ctx context.Context, d time.Duration) error {
87		t := time.NewTimer(d)
88		defer t.Stop()
89		select {
90		case <-ctx.Done():
91			return ctx.Err()
92		case <-t.C:
93			return nil
94		}
95	}
96	
97	// RelayResult 是单轮投递的结果统计。
98	type RelayResult struct {
99		// Claimed 本轮领取的事件数。
100		Claimed int
101		// Delivered 发送成功并 Ack 的事件数。
102		Delivered int
103		// Failed 发送失败并 Nack 保留的事件数。
104		Failed int
105	}
106	
107	// DeliverOnce 执行一轮领取与投递，不阻塞等待。没有事件时立即返回空结果。
108	// 单个事件发送失败不影响同批其它事件；失败事件被 Nack，可在后续轮次继续领取。
109	func (r *Relay) DeliverOnce(ctx context.Context) (RelayResult, error) {
110		events, err := r.store.ClaimPendingEvents(ctx, r.batch)
111		if err != nil {
112			return RelayResult{}, err
113		}
114		res := RelayResult{Claimed: len(events)}
115		for _, ev := range events {
116			if err := ctx.Err(); err != nil {
117				// 退出前把尚未处理的已领取事件退回，避免它们滞留到进程重启。
118				_ = r.store.NackEvent(ctx, ev.ID)
119				res.Failed++
120				continue
121			}
122			if err := r.publisher.Publish(ctx, *ev); err != nil {
123				if nackErr := r.store.NackEvent(ctx, ev.ID); nackErr != nil {
124					return res, nackErr
125				}
126				res.Failed++
127				continue
128			}
129			if err := r.store.AckEvent(ctx, ev.ID); err != nil {
130				return res, err
131			}
132			res.Delivered++
133		}
134		return res, nil
135	}
136	
137	// Run 循环执行投递，直到 ctx 被取消。至少一轮成功投递后返回 ctx.Err()。
138	// 全部事件发送失败的批次后按重试间隔等待；无事件时按空闲间隔等待。
139	func (r *Relay) Run(ctx context.Context) error {
140		for {
141			if err := ctx.Err(); err != nil {
142				return err
143			}
144			res, err := r.DeliverOnce(ctx)
145			if err != nil {
146				return err
147			}
148			var wait time.Duration
149			switch {
150			case res.Claimed == 0:
151				wait = r.idleWait
152			case res.Failed > 0 && res.Delivered == 0:
153				wait = r.retryBackoff
154			default:
155				wait = 0 // 本轮有成功投递，立即继续领取，尽快排空积压
156			}
157			if wait > 0 {
158				if err := r.sleep(ctx, wait); err != nil {
159					return err
160				}
161			}
162		}
163	}
