// 在每次领取前执行，使失联 worker 持有的事件自动恢复为可领取。
func (s *MemoryStore) recoverExpiredLeasesLocked(now time.Time) {
    if len(s.leased) == 0 {
        return
    }
    kept := s.leased[:0]
    for _, id := range s.leased {
        me, ok := s.events[id]
        if !ok || !me.claimed || me.claimedUntil.IsZero() {
            continue // 已 Ack/Nack 或非租约领取，移出租约跟踪
